<template>
	<view class="container">
		<u-loading-page :loading="true" v-if="load" fontSize="28rpx" />
		<block v-else>
		<my-tab :datas="tabs" bgColor="#fff" height="80rpx" :current="type" @itemClick='itemClick' />
		<scroll-view scroll-y="true" class="scroll" @scrolltolower="loadMore">
			<block v-if="lists.length>0">
			<view class="order-items">
				<view style="height: 20rpx;"></view>
				<view class="order-item" v-for="(item,index) in lists" :key="index" @click="toNext(`/pages/order/order-detail?order_id=${item.order_id}`)">
					<view class="order-item-top">
						<view class="order-item-top-left">
							<text class="order-sn-text">{{item.add_time}}</text>
						</view>
						<view class="order-item-top-right">{{item.status_text}}</view>
					</view>
					<view class="goods">
						<view class="goods-item" v-for="(child,childIndex) in item.order_goods" :key="childIndex">
							<image :src="child.goods_img" class="goods-img" mode="aspectFit"/>
							<view class="goods-item-right">
								<view class="goods-name">{{child.goods_name}}</view>
								<view class="goods-spec">已选:{{child.item_name?child.item_name:'无'}}</view>
								<view class="goods-item-bot">
									<view class="goods-price">
										<text>¥</text>
										<text class="jiage">{{child.goods_price}}</text>
									</view>
									<view class="goods-num">x{{child.goods_num}}</view>
								</view>
							</view>
						</view>
					</view>
					<view class="order-item-info">
						<view class="info-right">
							<text class="small-text">实付：</text>
							<text class="fh-text">¥</text>
							<text class="price-text">{{item.order_amount}}</text>
						</view>
					</view>
					<view class="order-item-bot" v-if="item.order_status==1">
						<button class="order-item-btn theme" @click.stop="set_ps(item)">设为配送</button>
					</view>
					<view class="order-item-empty" v-else></view>
				</view>
				<u-loadmore class="load-more" :status="hasMore?'loading':'nomore'" :nomoreText="noMore" />
			</view>
			</block>
			<view class="empty-container" v-else>
				<u-empty text="暂无相关订单" :icon="emptyIcon" />
			</view>
		</scroll-view>
		</block>
	</view>
</template>

<script>
	var _this;
	export default {
		data() {
			return {
				tabs: [{
					name: '全部',
				}, {
					name: '待支付',
				}, {
					name: '待配送',
				}, {
					name: '待收货',
				}, {
					name: '已完成',
				}],
				page: 1,
				pageNum: 10,
				type:0
			};
		},
		methods: {
			itemClick(type) {
				_this.type = type
				_this.page = 1
				_this.lists = []
				_this.get_dingdan()
			},
			loadMore(){
				if(_this.hasMore){
					_this.page++
					_this.get_dingdan()
				}
			},
			async get_dingdan(){
				const params = {
					pageIndex: _this.page,
					pageSize: _this.pageNum,
					status: _this.type,
				}
				const data = await _this.$post('port/admin_dingdan_list', params)
				if(data.code==200){
					_this.lists.push(...data.result.list)
					_this.hasMore = data.result.list.length >= _this.pageNum
					if (_this.load) {
						_this.load = false
					}
				}else if (data.code == 100) {
					_this.hasMore = false
					this.$u.toast(data.msg,()=>{
						_this.finish()
					})
				}else{
					_this.hasMore = false
				}
			},
			//设为配送
			async set_ps(item){
				uni.showModal({
					title:'提示',
					content:'确定操作?',
					success(res) {
						if(res.confirm){
							_this.dd_ps(item)
						}
					}
				})
			},
			async dd_ps(item){
				const params = {
					id: item.order_id,
				}
				const data = await _this.$post('port/dingdan_set_ps', params)
				if(data.code==200){
					item.order_status = 2
					item.status_text = '待收货'
					this.$u.toast(data.msg)
				}else{
					this.$u.toast(data.msg)
				}
			},
		},
		onLoad(e) {
			_this = this;
			if(e.type){
				_this.type = e.type
			}
			_this.get_dingdan()
		},
		components: {}
	}
</script>

<style lang="scss" scoped>
	@import "static/css/order.scss";
	.container {
		height: 100%;
		.scroll{
			height: calc(100% - 80rpx);
			.order-items{
				padding: 0 30rpx;
			}
		}
	}
</style>